/* =============================================================================
 * SUNSTEP: Featherfronds of the Suneater Owlbear
 * -----------------------------------------------------------------------------
 * Foundry VTT v12 to v13, dnd5e 3.x to 5.x.
 * Runs as a Midi-QOL on-use macro, a DAE/Item Macro, or a hotbar macro
 * (select the token first). Sequencer + JB2A are optional; without them the
 * teleport still works, just without visual effects.
 *
 * Behaviour
 *  - Checks the item has a use remaining.
 *  - Optionally checks that the origin is in bright light.
 *  - Shows a range overlay drawn in world space, so zooming (wheel) and
 *    panning (right-drag) never disturb it. Line widths and labels rescale
 *    with zoom so they stay legible.
 *  - Ghost preview of the token at the cursor, coloured:
 *      green = valid, amber = valid but no bright light detected, red = invalid
 *  - Left-click confirms; Esc or the Cancel button aborts. Shift places freely.
 *  - True teleport: ignores walls and paths entirely; only the destination
 *    must be unoccupied, in range, on the scene and visible to you.
 *  - Departure, transit and arrival effects and sounds, each optional.
 *  - Rolls the depletion die; on a 1, the item's uses are emptied until dawn.
 * ============================================================================= */

// ----------------------------- CONFIGURATION ---------------------------------
const SUN = {
  itemName: "Suneater Featherfronds", // fallback lookup when not launched from the item
  rangeFt: 60,                         // converted automatically on metric scenes
  depletionFormula: "1d6",
  depletionOn: 1,                      // a result at or below this depletes the item
  lightCheck: "warn",                  // "off" | "warn" (ask) | "enforce" (block)
  snapToGrid: true,                    // hold Shift while aiming to ignore the grid
  fadeToken: true,                     // fade out at origin, fade in at destination

  // Each entry may be a single Sequencer database key / file path, an array of
  // fallbacks (the first one that exists is used), or null to skip it.
  fx: {
    departure: ["jb2a.misty_step.01.yellow", "jb2a.misty_step.01.orange", "jb2a.misty_step.01.blue"],
    transit:   ["jb2a.disintegrate.orangepink"], // e.g. "jb2a.energy_strands.range.standard.orange" (stretched origin to destination)
    arrival:   ["jb2a.misty_step.02.yellow", "jb2a.misty_step.02.orange", "jb2a.misty_step.02.blue"],
    scale: 2       // effect size relative to the token's footprint
  },
  sfx: {
    departure: null, // e.g. "modules/your-sounds/teleport-out.ogg"
    transit:   "sounds/Spells/Ray/spell-ray-4.mp3",
    arrival:   null,
    volume: 0.6
  },
  timing: { vanishMs: 450, transitMs: 350, reappearMs: 150 },
  colours: { range: 0xffc83d, valid: 0x4cd964, dim: 0xffa500, invalid: 0xff3b30 }
};
// -----------------------------------------------------------------------------

const wait = ms => new Promise(r => setTimeout(r, ms));
const GRID = CONST.GRID_TYPES;

if (globalThis.__sunstepActive) {
  ui.notifications.warn("Sunstep: targeting is already in progress.");
  return false;
}

// ---------------------------- RESOLVE CONTEXT --------------------------------
const A = (typeof args !== "undefined" && Array.isArray(args)) ? (args[0] ?? {}) : {};
const fromU = uuid => { try { return uuid ? fromUuidSync(uuid) : null; } catch { return null; } };

let sItem = fromU(A.itemUuid) ?? A.workflow?.item ?? (typeof item !== "undefined" ? item : null);
if (sItem && !(sItem instanceof Item)) sItem = sItem.item ?? fromU(sItem.uuid) ?? null; // activity or plain data

let tokDoc = fromU(A.tokenUuid)
  ?? (typeof token !== "undefined" ? token?.document : null)
  ?? canvas.tokens.controlled[0]?.document
  ?? null;
const sActor = tokDoc?.actor ?? sItem?.actor ?? (typeof actor !== "undefined" ? actor : null);
if (!sItem && sActor) sItem = sActor.items.getName(SUN.itemName);
if (!tokDoc && sActor) tokDoc = sActor.getActiveTokens(false, true)[0] ?? null;

const tok = tokDoc?.object;
if (!tok || tokDoc.parent !== canvas.scene) {
  ui.notifications.error("Sunstep: no token for this actor on the current scene.");
  return false;
}
if (!sItem) {
  ui.notifications.error(`Sunstep: could not find the item ("${SUN.itemName}").`);
  return false;
}

// ---------------------------------- USES -------------------------------------
function usesInfo(it) {
  const u = it.system.uses ?? {};
  const max = Number(u.max) || 0;
  const spentModel = foundry.utils.hasProperty(it._source, "system.uses.spent"); // dnd5e 4+
  const value = spentModel ? Math.max(0, max - (Number(u.spent) || 0)) : Number(u.value ?? 0);
  return { max, value, spentModel };
}
async function depleteUses(it) {
  const { max, spentModel } = usesInfo(it);
  if (!max) return;
  await it.update(spentModel ? { "system.uses.spent": max } : { "system.uses.value": 0 });
}

const uses = usesInfo(sItem);
if (uses.max > 0 && uses.value <= 0) {
  ui.notifications.warn(`${sItem.name}: Sunstep is spent until the next dawn.`);
  return false;
}
if (!uses.max) ui.notifications.warn(`${sItem.name}: no Limited Uses configured, so depletion cannot be tracked.`);

// ------------------------------ GEOMETRY -------------------------------------
const units = String(canvas.grid.units ?? canvas.scene.grid?.units ?? canvas.scene.gridUnits ?? "ft").toLowerCase();
const range = /^m/.test(units) ? SUN.rangeFt * 0.3 : SUN.rangeFt;
const pxPerUnit = canvas.dimensions.distancePixels ?? (canvas.dimensions.size / canvas.dimensions.distance);
const rangePx = range * pxPerUnit;
const gs = canvas.grid.size;
const gridType = canvas.grid.type;
const W = tok.w, H = tok.h;
const origin = { x: tok.center.x, y: tok.center.y };

function measure(a, b) {
  if (gridType === GRID.GRIDLESS) return Math.hypot(b.x - a.x, b.y - a.y) / pxPerUnit;
  if (canvas.grid.measurePath) return canvas.grid.measurePath([a, b]).distance;
  return canvas.grid.measureDistance(a, b, { gridSpaces: true });
}

function snapTopLeft(pos) {
  const shift = game.keyboard?.isModifierActive?.("Shift");
  if (!SUN.snapToGrid || shift || gridType === GRID.GRIDLESS) return pos;
  try {
    if (tokDoc.getSnappedPosition) return tokDoc.getSnappedPosition(pos);
    if (tok.getSnappedPosition) return tok.getSnappedPosition(pos);
    return canvas.grid.getSnappedPosition(pos.x, pos.y, 1);
  } catch { return pos; }
}

const overlaps = (a, b) => a.x < b.x + b.width && a.x + a.width > b.x && a.y < b.y + b.height && a.y + a.height > b.y;
function occupant(tl) {
  const r = { x: tl.x + 2, y: tl.y + 2, width: W - 4, height: H - 4 };
  return canvas.tokens.placeables.find(t =>
    t.id !== tok.id && !(t.document.hidden && !game.user.isGM) && overlaps(r, t.bounds));
}

function canSee(p) {
  try { return canvas.visibility?.testVisibility?.(p, { tolerance: 2 }) ?? true; } catch { return true; }
}

/** true = bright light found, false = none found, null = could not determine */
function isBright(p) {
  try {
    const gl = canvas.environment?.globalLightSource ?? canvas.effects?.illumination?.globalLight ?? null;
    if (gl?.active) return true;
    if (game.release.generation < 12 && canvas.scene.globalLight
        && canvas.darknessLevel <= (canvas.scene.globalLightThreshold ?? 1)) return true;
    for (const src of canvas.effects?.lightSources ?? []) {
      if (!src?.active || src === gl || src.isDarkness) continue;
      if (src.constructor?.name?.includes("Global")) continue;
      const r = src.data?.bright ?? 0; // pixels
      if (r <= 0) continue;
      const sx = src.data?.x ?? src.x, sy = src.data?.y ?? src.y;
      if (Math.hypot(p.x - sx, p.y - sy) > r) continue;
      if (src.shape?.contains?.(p.x, p.y) ?? true) return true;
    }
    return false;
  } catch (err) {
    console.warn("Sunstep | light check failed", err);
    return null;
  }
}

function evaluate(world) {
  const tl = snapTopLeft({ x: world.x - W / 2, y: world.y - H / 2 });
  const c = { x: tl.x + W / 2, y: tl.y + H / 2 };
  const dist = measure(origin, c);
  let reason = null;
  if (Math.abs(tl.x - tokDoc.x) < 1 && Math.abs(tl.y - tokDoc.y) < 1) reason = "That is your current space";
  else if (!canvas.dimensions.sceneRect.contains(c.x, c.y)) reason = "Outside the scene";
  else if (dist > range + 0.01) reason = `Out of range (${Math.round(dist)} ${units})`;
  else if (occupant(tl)) reason = "Space occupied";
  else if (!canSee(c)) reason = "You cannot see that space";
  const bright = SUN.lightCheck === "off" ? true : isBright(c);
  return { tl, c, dist, reason, bright };
}

async function confirmDialog(title, text) {
  const D2 = foundry.applications?.api?.DialogV2;
  if (D2) return D2.confirm({ window: { title }, content: `<p>${text}</p>`, rejectClose: false, modal: true });
  return Dialog.confirm({ title, content: `<p>${text}</p>` });
}

// ------------------------- ORIGIN LIGHT CHECK --------------------------------
if (SUN.lightCheck !== "off" && isBright(origin) === false) {
  const msg = "You do not appear to be standing in bright light.";
  if (SUN.lightCheck === "enforce") { ui.notifications.warn(`Sunstep: ${msg}`); return false; }
  const ok = await confirmDialog("Sunstep", `${msg} Use Sunstep anyway?`);
  if (!ok) return false;
}

// ------------------------------ TARGETING ------------------------------------
async function pickDestination() {
  const layer = canvas.controls ?? canvas.interface;
  const root = new PIXI.Container();
  root.eventMode = "none";
  layer.addChild(root);

  // Static reachable-area fill (square grids honour the diagonal rule)
  const fill = new PIXI.Graphics();
  fill.beginFill(SUN.colours.range, 0.13);
  if (gridType === GRID.SQUARE) {
    const x0 = Math.floor((origin.x - rangePx) / gs) * gs - gs;
    const y0 = Math.floor((origin.y - rangePx) / gs) * gs - gs;
    for (let x = x0; x <= origin.x + rangePx + gs; x += gs) {
      for (let y = y0; y <= origin.y + rangePx + gs; y += gs) {
        if (measure(origin, { x: x + gs / 2, y: y + gs / 2 }) <= range + 0.01) fill.drawRect(x, y, gs, gs);
      }
    }
  } else {
    fill.drawCircle(origin.x, origin.y, rangePx);
  }
  fill.endFill();
  root.addChild(fill);

  const dyn = new PIXI.Graphics();
  root.addChild(dyn);

  let ghost = null;
  try {
    const load = foundry.canvas?.loadTexture ?? globalThis.loadTexture;
    const tex = await load(tokDoc.texture.src);
    if (tex) {
      ghost = new PIXI.Sprite(tex);
      ghost.width = W; ghost.height = H; ghost.alpha = 0.5;
      root.addChild(ghost);
    }
  } catch { /* preview image is optional */ }

  const label = new PIXI.Text("", {
    fontFamily: "Signika, sans-serif", fontSize: 26, fill: 0xffffff,
    stroke: 0x000000, strokeThickness: 5, align: "center"
  });
  label.anchor.set(0.5, 1);
  label.resolution = 2;
  root.addChild(label);

  // HTML banner with instructions and a Cancel button
  const banner = document.createElement("div");
  banner.style.cssText = [
    "position:fixed", "top:64px", "left:50%", "transform:translateX(-50%)", "z-index:10000",
    "background:rgba(22,17,8,0.94)", "border:1px solid #ffc83d", "border-radius:8px",
    "padding:8px 14px", "color:#f5ecd4", "font-family:var(--font-primary, Signika), sans-serif",
    "font-size:14px", "display:flex", "gap:14px", "align-items:center",
    "box-shadow:0 2px 14px rgba(0,0,0,0.6)", "pointer-events:auto"
  ].join(";");
  banner.innerHTML = `
    <div style="line-height:1.35">
      <div><i class="fas fa-sun" style="color:#ffc83d"></i> <b>Sunstep</b>: left-click a destination within ${range} ${units}</div>
      <div style="font-size:12px;opacity:0.85">Right-drag pans, wheel zooms, hold Shift to ignore the grid, Esc cancels.
        <span style="color:#4cd964">Green</span> valid; <span style="color:#ffa500">amber</span> no bright light detected; <span style="color:#ff3b30">red</span> invalid.</div>
    </div>
    <button type="button" style="width:auto;flex:0 0 auto;white-space:nowrap"><i class="fas fa-times"></i> Cancel</button>`;
  document.body.appendChild(banner);

  const view = canvas.app.view ?? canvas.app.canvas;
  const toWorld = e => canvas.canvasCoordinatesFromClient?.({ x: e.clientX, y: e.clientY }) ?? canvas.mousePosition;

  return new Promise(resolve => {
    let done = false, busy = false, down = null, lastScale = -1;

    const tick = () => {
      const p = canvas.mousePosition;
      if (!p || root.destroyed) return;
      const s = canvas.stage.scale.x;
      const ev = evaluate(p);
      const col = ev.reason ? SUN.colours.invalid : (ev.bright === false ? SUN.colours.dim : SUN.colours.valid);

      dyn.clear();
      if (gridType !== GRID.SQUARE) dyn.lineStyle(3 / s, SUN.colours.range, 0.9).drawCircle(origin.x, origin.y, rangePx);
      dyn.lineStyle(2 / s, SUN.colours.range, 0.9).drawRect(tokDoc.x, tokDoc.y, W, H);
      dyn.lineStyle(2 / s, col, 0.85).moveTo(origin.x, origin.y).lineTo(ev.c.x, ev.c.y);
      dyn.lineStyle(3 / s, col, 1).beginFill(col, 0.18).drawRect(ev.tl.x, ev.tl.y, W, H).endFill();

      if (ghost) { ghost.position.set(ev.tl.x, ev.tl.y); ghost.tint = ev.reason ? 0xff8080 : 0xffffff; }

      label.text = ev.reason ?? `${Math.round(ev.dist)} ${units}${ev.bright === false ? "\nno bright light detected" : ""}`;
      if (s !== lastScale) { label.scale.set(1 / s); lastScale = s; }
      label.position.set(ev.c.x, ev.tl.y - 6 / s);
    };

    const onDown = e => {
      if (e.target !== view || e.button !== 0) return;
      e.stopImmediatePropagation(); e.preventDefault();
      down = { x: e.clientX, y: e.clientY };
    };

    const onUp = async e => {
      if (e.target !== view || e.button !== 0) return;
      e.stopImmediatePropagation(); e.preventDefault();
      if (!down || busy) return;
      const moved = Math.hypot(e.clientX - down.x, e.clientY - down.y);
      down = null;
      if (moved > 6) return; // a drag, not a click
      const ev = evaluate(toWorld(e));
      if (ev.reason) return ui.notifications.warn(`Sunstep: ${ev.reason}.`);
      if (ev.bright === false && SUN.lightCheck === "enforce") {
        return ui.notifications.warn("Sunstep: the destination must be in bright light.");
      }
      if (ev.bright === false && SUN.lightCheck === "warn") {
        busy = true;
        const ok = await confirmDialog("Sunstep", "No bright light was detected at that destination. Teleport there anyway?");
        busy = false;
        if (!ok) return;
      }
      finish(ev);
    };

    const onKey = e => {
      if (e.key !== "Escape" || busy) return;
      e.stopImmediatePropagation(); e.preventDefault();
      finish(null);
    };

    const hookId = Hooks.on("canvasTearDown", () => finish(null));

    function finish(result) {
      if (done) return;
      done = true;
      canvas.app.ticker.remove(tick);
      document.removeEventListener("pointerdown", onDown, true);
      document.removeEventListener("pointerup", onUp, true);
      window.removeEventListener("keydown", onKey, true);
      Hooks.off("canvasTearDown", hookId);
      banner.remove();
      if (!root.destroyed) root.destroy({ children: true });
      resolve(result);
    }

    banner.querySelector("button").addEventListener("click", () => finish(null));
    document.addEventListener("pointerdown", onDown, true);
    document.addEventListener("pointerup", onUp, true);
    window.addEventListener("keydown", onKey, true);
    canvas.app.ticker.add(tick);
  });
}

// ------------------------------ EFFECTS --------------------------------------
const hasSequencer = game.modules.get("sequencer")?.active && typeof Sequence !== "undefined";

function resolveFx(entry) {
  if (!hasSequencer || !entry) return null;
  for (const f of [].concat(entry)) {
    if (!f) continue;
    if (f.includes("/")) return f; // direct file path
    try { if (Sequencer.Database.entryExists(f)) return f; } catch { /* ignore */ }
  }
  return null;
}

function playFx(key, at, to = null) {
  const file = resolveFx(SUN.fx[key]);
  if (!file) return;
  const e = new Sequence().effect().file(file).atLocation(at);
  if (to) e.stretchTo(to);
  else e.size(Math.max(W, H) * SUN.fx.scale);
  e.play();
}

function playSfx(key) {
  const src = SUN.sfx[key];
  if (!src) return;
  const AH = foundry.audio?.AudioHelper ?? globalThis.AudioHelper;
  AH?.play({ src, volume: SUN.sfx.volume, autoplay: true, loop: false }, true);
}

async function teleport(dest) {
  const from = { ...origin }, to = dest.c;
  const origAlpha = tokDoc.alpha ?? 1;

  playSfx("departure");
  playFx("departure", from);
  await wait(SUN.timing.vanishMs);

  try {
    if (SUN.fadeToken) await tokDoc.update({ alpha: 0 }, { animation: { duration: 200 } });
    playSfx("transit");
    playFx("transit", from, to);
    await wait(SUN.timing.transitMs);

    // Direct document update: no wall, path or token collision is evaluated.
    await tokDoc.update({ x: dest.tl.x, y: dest.tl.y }, { animate: false, teleport: true });

    playSfx("arrival");
    playFx("arrival", to);
    await wait(SUN.timing.reappearMs);
  } finally {
    if (SUN.fadeToken) await tokDoc.update({ alpha: origAlpha }, { animation: { duration: 250 } });
  }
}

// -------------------------------- RUN ----------------------------------------
globalThis.__sunstepActive = true;
try {
  const dest = await pickDestination();
  if (!dest) {
    ui.notifications.info("Sunstep cancelled.");
    return false;
  }

  await teleport(dest);

  const roll = await new Roll(SUN.depletionFormula).evaluate();
  const depleted = roll.total <= SUN.depletionOn;
  if (depleted) await depleteUses(sItem);

  await roll.toMessage({
    speaker: ChatMessage.getSpeaker({ token: tokDoc, actor: sActor }),
    flavor: `<strong>${sItem.name}: Sunstep</strong><br>` + (depleted
      ? `<span style="color:#c0392b">The featherfronds dull; Sunstep cannot be used again until the next dawn.</span>`
      : `The featherfronds still shimmer; Sunstep remains available.`)
  });
} finally {
  globalThis.__sunstepActive = false;
}
